DROP SCHEMA IF EXISTS t2s_xmn2 CASCADE;
CREATE SCHEMA t2s_xmn2;
CREATE VIEW t2s_xmn2.branches AS SELECT branch_id AS salbar_id, branch_code AS salbar_kod, branch_name AS salbar_ner, branch_type AS salbar_torol, parent_branch_id AS parent_salbar_id, province AS aimag, district AS duureg, opened_date AS neesen_ognoo, closed_date AS haagd_ognoo, is_active AS is_idevh FROM t2s.branches;
CREATE VIEW t2s_xmn2.ajilt AS SELECT employee_id AS ajilt_id, employee_no AS ajilt_dugaar, first_name AS anh_ner, last_name AS suuli_ner, full_name AS full_ner, branch_id AS salbar_id, department_code AS heltes_kod, department_name AS heltes_ner, position_code AS alban_kod, position_name AS alban_ner, manager_id AS menej_id, hire_date AS hire_ognoo, termination_date AS termination_ognoo, employment_status AS ajil_tolov FROM t2s.employees;
CREATE VIEW t2s_xmn2.haril AS SELECT customer_id AS haril_id, customer_number AS haril_dugaar, customer_name AS haril_ner, party_type AS party_torol, customer_type_code AS haril_torol_kod, customer_type_name AS haril_torol_ner, status_code AS tolov_kod, status_name AS tolov_ner, segment_code AS segme_kod, segment_name AS segme_ner, branch_id AS salbar_id, relationship_manager_id AS relationship_menej_id, kyc_status AS kyc_tolov, aml_status AS aml_tolov, risk_level AS ersdel_tuvsh, is_pep AS is_pep, is_blacklisted AS is_blacklisted, is_resident AS is_resident, country_code AS country_kod, onboarded_date AS onboarded_ognoo, closed_date AS haagd_ognoo, province AS aimag, district AS duureg FROM t2s.customers;
CREATE VIEW t2s_xmn2.huvi_hun AS SELECT customer_id AS haril_id, gender AS gender, birth_year AS birth_jil, age AS age, marital_status AS marital_tolov, dependants_count AS dependants_too, education_level AS education_tuvsh, occupation AS occupation, employer_name AS employer_ner, employment_type AS ajil_torol, monthly_income AS sar_buriin_orlogo, income_currency AS orlogo_valyut FROM t2s.individuals;
CREATE VIEW t2s_xmn2.baigu AS SELECT customer_id AS haril_id, org_name AS org_ner, legal_form AS legal_form, industry_code AS uildv_kod, industry_sector AS uildv_sector, establishment_date AS establishment_ognoo, employee_count AS ajilt_too, annual_revenue AS jiliin_orlogo, revenue_currency AS orlogo_valyut_2 FROM t2s.organizations;
CREATE VIEW t2s_xmn2.butee AS SELECT product_id AS butee_id, product_code AS butee_kod, product_name AS butee_ner, product_type_code AS butee_torol_kod, product_type_name AS butee_torol_ner, category AS angil, currency_code AS valyut_kod, amortization_type AS amortization_torol, requires_collateral AS requires_barcaa, requires_guarantor AS requires_batlan_daagch, min_credit_score AS door_zeeli_onoo, max_dti_ratio AS deed_dti_haric, max_ltv_ratio AS deed_ltv_haric, launch_date AS launch_ognoo, discontinue_date AS discontinue_ognoo, status AS tolov, annual_rate AS jiliin_huvi, min_amount AS door_dun, max_amount AS deed_dun, min_term_months AS door_hugac_sar, max_term_months AS deed_hugac_sar FROM t2s.products;
CREATE VIEW t2s_xmn2.zeel_huselt AS SELECT application_id AS huselt_id, application_no AS huselt_dugaar, customer_id AS haril_id, product_id AS butee_id, branch_id AS salbar_id, loan_officer_id AS zeel_officer_id, status_code AS tolov_kod, status_name AS tolov_ner, channel AS suvag, requested_amount AS huses_dun, requested_term_months AS huses_hugac_sar, currency_code AS valyut_kod, purpose_category AS purpose_angil, declared_income AS declared_orlogo, dti_ratio AS dti_haric, approved_amount AS batla_dun, approved_term_months AS batla_hugac_sar, approved_rate AS batla_huvi, credit_score AS zeeli_onoo, decision_level AS shiid_tuvsh, submitted_date AS submitted_ognoo, decided_date AS decided_ognoo, rejection_reason AS rejection_shalt FROM t2s.loan_applications;
CREATE VIEW t2s_xmn2.zeel AS SELECT loan_id AS zeel_id, loan_number AS zeel_dugaar, application_id AS huselt_id, customer_id AS haril_id, product_id AS butee_id, branch_id AS salbar_id, loan_officer_id AS zeel_officer_id, status_code AS tolov_kod, status_name AS tolov_ner, is_active_portfolio AS is_idevh_portfolio, currency_code AS valyut_kod, principal_amount AS undsen_dun, interest_rate AS huu_huvi, penalty_rate AS torgu_huvi, effective_rate AS huchi_huvi, term_months AS hugac_sar, amortization_type AS amortization_torol, contract_date AS contract_ognoo, disbursement_date AS disbursement_ognoo, first_payment_date AS anh_tulbur_ognoo, maturity_date AS duusah_ognoo, closed_date AS haagd_ognoo, disbursed_amount AS disbursed_dun, principal_outstanding AS undsen_uldeg, interest_outstanding AS huu_uldeg, penalty_outstanding AS torgu_uldeg, fee_outstanding AS shimt_uldeg, total_outstanding AS niit_uldeg, principal_paid AS undsen_tulsun, interest_paid AS huu_tulsun, penalty_paid AS torgu_tulsun, fee_paid AS shimt_tulsun, written_off_amount AS written_off_dun, overdue_principal AS heter_undsen, overdue_interest AS heter_huu, days_past_due AS honog_heter_tuluh, max_days_past_due AS deed_honog_heter_tuluh, dpd_bucket AS dpd_buleg, classification_code AS angil_kod, classification_name AS angil_ner, provision_rate AS provision_huvi, is_npl AS is_npl, is_restructured AS is_restructured, restructure_count AS buciin_uurch_too, last_payment_date AS suuli_tulbur_ognoo, fx_rate_to_mnt AS fx_huvi_to_mnt, principal_amount_mnt AS undsen_dun_mnt, principal_outstanding_mnt AS undsen_uldeg_mnt, total_outstanding_mnt AS niit_uldeg_mnt FROM t2s.loans;
CREATE VIEW t2s_xmn2.zeel_huvaa AS SELECT loan_id AS zeel_id, installment_no AS installment_dugaar, due_date AS tuluh_ognoo, principal_due AS undsen_tuluh, interest_due AS huu_tuluh, total_due AS niit_tuluh, principal_paid AS undsen_tulsun, interest_paid AS huu_tulsun, penalty_charged AS torgu_charged, penalty_paid AS torgu_tulsun, status AS tolov, paid_date AS tulsun_ognoo, days_past_due AS honog_heter_tuluh, schedule_version AS huvaa_version FROM t2s.loan_schedule;
CREATE VIEW t2s_xmn2.zeel_tulbur AS SELECT payment_id AS tulbur_id, payment_no AS tulbur_dugaar, loan_id AS zeel_id, customer_id AS haril_id, branch_id AS salbar_id, currency_code AS valyut_kod, amount AS dun, payment_date AS tulbur_ognoo, payment_method AS tulbur_arga, payment_type AS tulbur_torol, allocated_principal AS huvaa_undsen, allocated_interest AS huvaa_huu, allocated_penalty AS huvaa_torgu, allocated_fee AS huvaa_shimt, unallocated_amount AS unallocated_dun, status AS tolov FROM t2s.loan_payments;
CREATE VIEW t2s_xmn2.zeel_dpd_tuuh AS SELECT loan_id AS zeel_id, snapshot_date AS snapshot_ognoo, days_past_due AS honog_heter_tuluh, dpd_bucket AS dpd_buleg, overdue_principal AS heter_undsen, overdue_interest AS heter_huu, overdue_penalty AS heter_torgu, total_outstanding AS niit_uldeg, classification_code AS angil_kod FROM t2s.loan_dpd_history;
CREATE VIEW t2s_xmn2.zeel_huraa AS SELECT loan_id AS zeel_id, charge_type AS huraa_torol, charge_code AS huraa_kod, charge_name AS huraa_ner, currency_code AS valyut_kod, amount AS dun, charged_date AS charged_ognoo, paid_amount AS tulsun_dun, waived_amount AS waived_dun, status AS tolov, days_overdue AS honog_heter FROM t2s.loan_charges;
CREATE VIEW t2s_xmn2.zeel_buciin_uurch AS SELECT loan_id AS zeel_id, restructure_no AS buciin_uurch_dugaar, restructure_type AS buciin_uurch_torol, reason AS shalt, old_principal AS huuch_undsen, new_principal AS shine_undsen, old_rate AS huuch_huvi, new_rate AS shine_huvi, old_term_months AS huuch_hugac_sar, new_term_months AS shine_hugac_sar, old_maturity_date AS huuch_duusah_ognoo, new_maturity_date AS shine_duusah_ognoo, effective_date AS huchi_ognoo, status AS tolov FROM t2s.loan_restructures;
CREATE VIEW t2s_xmn2.zeel_hasalt AS SELECT loan_id AS zeel_id, writeoff_date AS hasalt_ognoo, principal_amount AS undsen_dun, interest_amount AS huu_dun, penalty_amount AS torgu_dun, fee_amount AS shimt_dun, total_amount AS niit_dun, writeoff_type AS hasalt_torol, recovered_amount AS serge_dun FROM t2s.loan_writeoffs;
CREATE VIEW t2s_xmn2.barcaa AS SELECT collateral_id AS barcaa_id, collateral_number AS barcaa_dugaar, collateral_type_code AS barcaa_torol_kod, collateral_type_name AS barcaa_torol_ner, collateral_category AS barcaa_angil, owner_customer_id AS owner_haril_id, branch_id AS salbar_id, market_value AS market_utga, forced_sale_value AS forced_sale_utga, accepted_value AS accepted_utga, currency_code AS valyut_kod, valuation_date AS unelg_ognoo, next_valuation_date AS next_unelg_ognoo, is_insured AS is_insured, encumbrance_status AS encumbrance_tolov, status AS tolov FROM t2s.collaterals;
CREATE VIEW t2s_xmn2.zeel_barcaa AS SELECT loan_id AS zeel_id, collateral_id AS barcaa_id, currency_code AS valyut_kod, allocated_amount AS huvaa_dun, ltv_ratio AS ltv_haric, pledge_date AS pledge_ognoo, release_date AS release_ognoo, status AS tolov FROM t2s.loan_collaterals;
CREATE VIEW t2s_xmn2.zeel_batlan_daagch AS SELECT loan_id AS zeel_id, guarantor_id AS batlan_daagch_id, guarantor_type AS batlan_daagch_torol, is_existing_customer AS is_existing_haril, guarantor_customer_id AS batlan_daagch_haril_id, currency_code AS valyut_kod, guarantee_amount AS batal_dun, guarantee_pct AS batal_pct, liability_type AS liability_torol, valid_from AS huchi_from, valid_to AS huchi_to, called_date AS duuds_ognoo, called_amount AS duuds_dun, recovered_amount AS serge_dun, status AS tolov FROM t2s.loan_guarantors;
CREATE VIEW t2s_xmn2.dans AS SELECT account_id AS dans_id, customer_id AS haril_id, branch_id AS salbar_id, product_id AS butee_id, account_type_code AS dans_torol_kod, account_type_name AS dans_torol_ner, currency_code AS valyut_kod, current_balance AS odoog_uldeg, available_balance AS available_uldeg, hold_amount AS hold_dun, status AS tolov, is_dormant AS is_dormant, opened_date AS neesen_ognoo, closed_date AS haagd_ognoo, last_transaction_date AS suuli_guilg_ognoo FROM t2s.accounts;
CREATE VIEW t2s_xmn2.guilg AS SELECT transaction_id AS guilg_id, transaction_no AS guilg_dugaar, account_id AS dans_id, customer_id AS haril_id, branch_id AS salbar_id, transaction_type_code AS guilg_torol_kod, transaction_type_name AS guilg_torol_ner, category AS angil, channel_code AS suvag_kod, channel_name AS suvag_ner, status_code AS tolov_kod, direction AS direction, amount AS dun, fee_amount AS shimt_dun, currency_code AS valyut_kod, amount_mnt AS dun_mnt, transaction_date AS guilg_ognoo, value_date AS utga_ognoo FROM t2s.transactions;
CREATE VIEW t2s_xmn2.dans_uldeg_sar_buriin AS SELECT account_id AS dans_id, balance_date AS uldeg_ognoo, opening_balance AS opening_uldeg, total_debit AS niit_debit, total_credit AS niit_zeeli, closing_balance AS haalt_uldeg, transaction_count AS guilg_too, currency_code AS valyut_kod, closing_balance_mnt AS haalt_uldeg_mnt FROM t2s.account_balances_monthly;
CREATE VIEW t2s_xmn2.hadga AS SELECT deposit_id AS hadga_id, deposit_number AS hadga_dugaar, account_id AS dans_id, customer_id AS haril_id, product_id AS butee_id, branch_id AS salbar_id, currency_code AS valyut_kod, deposit_type AS hadga_torol, principal_amount AS undsen_dun, current_balance AS odoog_uldeg, interest_rate AS huu_huvi, interest_method AS huu_arga, term_months AS hugac_sar, accrued_interest AS accrued_huu, paid_interest AS tulsun_huu, withholding_tax_paid AS withholding_tax_tulsun, opened_date AS neesen_ognoo, maturity_date AS duusah_ognoo, closed_date AS haagd_ognoo, auto_renew AS auto_renew, renewal_count AS renewal_too, is_pledged AS is_pledged, status AS tolov, current_balance_mnt AS odoog_uldeg_mnt FROM t2s.deposits;
CREATE VIEW t2s_xmn2.barag_keis AS SELECT case_id AS keis_id, case_no AS keis_dugaar, loan_id AS zeel_id, customer_id AS haril_id, branch_id AS salbar_id, stage_code AS shat_kod, stage_name AS shat_ner, currency_code AS valyut_kod, opened_date AS neesen_ognoo, dpd_at_open AS dpd_at_nee, current_dpd AS odoog_dpd, outstanding_at_open AS uldeg_at_nee, current_outstanding AS odoog_uldeg_2, overdue_amount AS heter_dun, collected_amount AS collected_dun, assigned_to AS assigned_to, agency_code AS agent_kod, agency_name AS agent_ner, priority AS priority, status AS tolov, closed_date AS haagd_ognoo, close_reason AS close_shalt FROM t2s.collection_cases;
CREATE VIEW t2s_xmn2.barag_uildel AS SELECT action_id AS uildel_id, case_id AS keis_id, action_code AS uildel_kod, action_name AS uildel_ner, channel AS suvag, action_date AS uildel_ognoo, performed_by AS performed_by, agency_code AS agent_kod, contact_result AS contact_result, cost_amount AS cost_dun FROM t2s.collection_actions;
CREATE VIEW t2s_xmn2.barag_amlalt AS SELECT promise_id AS amlalt_id, case_id AS keis_id, currency_code AS valyut_kod, promised_amount AS amlas_dun, promised_date AS amlas_ognoo, paid_amount AS tulsun_dun, paid_date AS tulsun_ognoo, status AS tolov FROM t2s.collection_promises;
CREATE VIEW t2s_xmn2.zeeli_onoo AS SELECT score_id AS onoo_id, customer_id AS haril_id, application_id AS huselt_id, model_code AS model_kod, model_name AS model_ner, score AS onoo, risk_grade_code AS ersdel_zereg_kod, risk_grade_name AS ersdel_zereg_ner, pd_estimate AS pd_estimate, decision_hint AS shiid_hint, score_type AS onoo_torol, scored_date AS scored_ognoo FROM t2s.credit_scores;
CREATE VIEW t2s_xmn2.aml_sanuu AS SELECT alert_id AS sanuu_id, alert_no AS sanuu_dugaar, rule_code AS durem_kod, rule_name AS durem_ner, customer_id AS haril_id, alert_amount AS sanuu_dun, currency_code AS valyut_kod, severity AS severity, status AS tolov, detected_date AS detected_ognoo, closed_date AS haagd_ognoo, str_reported AS str_reported FROM t2s.aml_alerts;
CREATE VIEW t2s_xmn2.gl_entries AS SELECT entry_no AS burtg_dugaar, line_no AS line_dugaar, posting_date AS posting_ognoo, period_code AS period_kod, fiscal_year AS fiscal_jil, branch_id AS salbar_id, journal_code AS jurnal_kod, journal_name AS jurnal_ner, account_code AS dans_kod, account_name_mn AS dans_ner_mn, account_type AS dans_torol, dr_cr AS dr_cr, amount AS dun, currency_code AS valyut_kod, amount_mnt AS dun_mnt, source_system AS source_system, entry_status AS burtg_tolov FROM t2s.gl_entries;
CREATE VIEW t2s_xmn2.solih_huvi AS SELECT currency_code AS valyut_kod, rate_date AS huvi_ognoo, buy_rate AS buy_huvi, sell_rate AS sell_huvi, mid_rate AS mid_huvi FROM t2s.exchange_rates;
GRANT USAGE ON SCHEMA t2s_xmn2 TO t2s_bot; GRANT SELECT ON ALL TABLES IN SCHEMA t2s_xmn2 TO t2s_bot;
